      note: 'Two eras under one body. Through 1994 it is the old two-key A/B system — ask whether the ignition or the door key is lost before you cut anything. From 1995 GM went to the single 10-cut key. The 3/4 and 1-ton kept selling as the "Classic" body through 2002 alongside the new GMT800, so a 2000 model year can be either truck: read the VIN, not the year.',
